<?php

declare(strict_types=1);

namespace App\Tests\Functional\Wiring;

use App\Security\DelegatedTokenIssuer;
use Symfony\Bundle\FrameworkBundle\Test\KernelTestCase;
use Symfony\Component\Routing\RouterInterface;

/**
 * A delegated token is only accepted on the routes of DelegatedTokenIssuer::ALLOWED_ROUTES: two of them are the names
 * generated by API Platform from their URI template. A renamed route would silently refuse the token (the statistics
 * papers of Episciences): each name must be a route of the application, on the expected path.
 *
 * Needs neither a database nor Solr.
 */
class DelegatedTokenRoutesTest extends KernelTestCase
{
    private const array EXPECTED_PATHS = [
        'get_stats_dashboard_item' => '/api/journals/stats/dashboard/{code}',
        '_api_/statistics/_get_collection' => '/api/statistics/',
        '_api_/statistics/evaluation_get_collection' => '/api/statistics/evaluation',
    ];

    public function testTheAllowedRoutesAreRoutesOfTheApplication(): void
    {
        self::bootKernel();

        /** @var RouterInterface $router */
        $router = static::getContainer()->get('router');
        $routes = $router->getRouteCollection();

        $this->assertSame(array_keys(self::EXPECTED_PATHS), DelegatedTokenIssuer::ALLOWED_ROUTES);

        foreach (self::EXPECTED_PATHS as $name => $path) {
            $route = $routes->get($name);

            $this->assertNotNull($route, sprintf('%s is not a route of the application', $name));
            $this->assertSame($path, preg_replace('/\.\{_format}$/', '', $route->getPath()), $name);
            $this->assertContains('GET', $route->getMethods(), $name);
        }
    }
}
